INSERT INTO destination_months (destination_id, month, score, verdict, note, why_go, why_not, prose_lead)
VALUES (
  'nagarjuna-sagar', 2, 5, 'go',
  'Driest stretch. 18-31C. Nagarjunakonda island museum at peak. NSTR safaris at year-best wildlife density.',
  'February holds January cleanliness. Rainfall under 10mm. Nagarjunakonda Island museum boats at full schedule. NSTR safaris at year-best wildlife density — tigers, leopards, panthers around waterholes. Ethipothala Falls walkable. Hotel rates ease 15 percent off January.',
  NULL,
  'February in Nagarjuna Sagar is the technical peak. Rainfall under 10mm, daytime 29-31C, nights 18-20C, humidity at 50 percent — the lowest of the year. Nagarjunakonda Island Buddhist heritage museum — the reconstructed monastery and stupa complex from the 3rd-c CE Iksvaku dynasty, originally submerged in 1960 when the dam reservoir filled, painstakingly relocated by the ASI to the Anupu hill island — at full ferry schedule (9:30am and 1:30pm from Vijayapuri South ghat). The museum holds the 9 major stupas, 26 monastery viharas and the spectacular Iksvaku-era sculpture panels. Nagarjuna Sagar-Srisailam Tiger Reserve (NSTR, 3,568 sq km, India''s largest tiger reserve) safari at year-peak wildlife density — vegetation cover thinning through the dry season pushes tigers, leopards, panthers, sloth bears, sambars and gaurs to waterholes around the reservoir backwater. Safari bookings via AP Forest Department / Telangana Forest, 6am-10am and 3pm-6pm slots, jeep ₹3,000-5,500 for 6 passengers. Hotel rates ease 15 percent off January: Haritha Hill Colony ₹2-3k, Project Tiger forest guest houses ₹1,000-2,000, mid-bracket lodges ₹800-1,500.'
)
