INSERT INTO destination_months (destination_id, month, score, verdict, note, why_go, why_not, prose_lead)
VALUES (
  'nagarjuna-sagar', 4, 3, 'wait',
  'Pre-monsoon. 24-36C, humidity 55 percent. NSTR safaris compress to dawn. Tiger density at year-peak.',
  'April pushes safaris to dawn only. Tiger and big-cat density at year-peak (waterholes dwindling) — for serious wildlife travelers this is the trade-off month. AC retreats handle mid-day. Nagarjunakonda boats compress to morning.',
  'April pushes Nagarjuna Sagar into pre-monsoon heat. Outdoor walks 10am-5pm unsafe. Tiger density at peak but heat tolerance required. October-March is dramatically more comfortable.',
  'April in Nagarjuna Sagar is the trade-off month — peak tiger-and-big-cat density at NSTR balanced against pre-monsoon heat. Daytime 33-36C, nights 24-25C, humidity 55 percent (low absolute but high temperature). Pre-monsoon thunderstorms hit the last fortnight — short squalls and dust storms. NSTR safaris compress to 6-9am dawn slots only (afternoon slots become unsafe except in the 5-6pm window). For serious wildlife travelers, April is the peak-tiger-density trade-off — water dries to absolute minimum across the 3,568 sq km reserve, tigers and big cats cluster at the 4-6 surviving waterholes around the reservoir backwater, and safari sighting probability sits at year-peak. Booking density tightens — book 7-10 days ahead via AP/Telangana Forest. Nagarjunakonda Island museum boats compress to the 9:30am ferry only. Ethipothala Falls walking unsafe through midday. The dam visitor access works dawn-and-dusk. Hotel rates run 25 percent below February: Haritha Hill Colony ₹1.5-2.2k, Project Tiger forest guest houses ₹800-1,500. October-March is dramatically more comfortable for the general visit; April-May works only for tiger-trophy-density specialists.'
)
