INSERT INTO destination_months (destination_id, month, score, verdict, note, why_go, why_not, prose_lead)
VALUES (
  'nagarjuna-sagar', 10, 4, 'go',
  'Season opens. 22-30C. NSTR reopens Oct 1. Dam at full reservoir. Nagarjunakonda boats clean.',
  'October is the season opener. NSTR reopens October 1 — winter safari season begins. Dam at full reservoir, Ethipothala still at high flow first half. Nagarjunakonda boats clean. Cyclone-watch first fortnight (inland less affected than coast).',
  NULL,
  'October in Nagarjuna Sagar is the proper return to coherent and the season-opener for NSTR. Rainfall drops to 80-120mm with the bulk falling in the first ten days; from October 15 onward the inland-Andhra circuit flips into clean mode. Daytime 27-30C, humidity falling from 78 to 68 percent. The Nagarjuna Sagar-Srisailam Tiger Reserve (NSTR — India''s largest tiger reserve at 3,568 sq km, Project Tiger since 1983) reopens October 1 — winter safari season begins, vegetation cover still high so wildlife sightings density moderate (peaks in March-May when water dries to minimum), but the comfortable weather and the recently-reopened tracks bring the photographic-grade safari experience. AP Forest Department / Telangana Forest 6am-10am and 3pm-6pm safari slots, jeep ₹3,000-5,500 for 6 passengers. Dam reservoir at full-storage level through the month. Ethipothala Falls still at high monsoon flow through the first half. Nagarjunakonda Island museum boat ferries at full schedule. Hotel rates run 25-30 percent below January peak: Haritha Hill Colony ₹1.8-2.6k, Project Tiger forest guest houses ₹1,000-1,800.'
)
