INSERT INTO destination_months (destination_id, month, score, verdict, note, why_go, why_not, prose_lead)
VALUES (
  'nagarjuna-sagar', 11, 5, 'go',
  'Peak window opens. 19-29C, sub-25mm rain. NSTR safari season. Dam at high storage. Karthika at temples.',
  'November is the year''s second-peak month. NSTR safari winter-season at full schedule. Dam at high storage. Karthika Pournami brings deepam lighting at the nearby temple cluster. Rates 25 percent below December-January.',
  NULL,
  'November in Nagarjuna Sagar is the year''s second-peak month behind January. Rainfall under 25mm, daytime 27-29C, nights 19-20C, humidity dropping below 60 percent. The Nagarjuna Sagar-Srisailam Tiger Reserve safari at full winter-season schedule — vegetation cover still high but visitor density and weather both balanced. Sightings of tigers, leopards, panthers, sloth bears, sambars and gaurs build through November-March cycle. Dam reservoir at high-storage level through the month. Ethipothala Falls at strong post-monsoon flow (22m drop). Nagarjunakonda Island museum boat ferries at peak schedule. The dam visitor access at peak comfort. Karthika Masam (mid-November to mid-December) brings mass deepam lighting at the broader Krishna-basin Shiva temples; the smaller Anupu temples and the Vijayapuri ghat-area shrines on the Nagarjuna Sagar reservoir bank participate. Karthika Pournami (full moon, mid-month) the peak night. Hotel rates climb to 80 percent of January peak: Haritha Hill Colony ₹2-3k, Project Tiger forest guest houses ₹1,200-2,200, mid-bracket lodges ₹900-1,800. Strong call for first-time visitors who want full circuit minus December-January peak.'
)
